DROP VIEW IF EXISTS `Product Sales for 1997`;
CREATE VIEW `Product Sales for 1997` AS
select `northwind`.`Categories`.`CategoryName` AS `CategoryName`,`northwind`.`Products`.`ProductName` AS `ProductName`,sum(round(((`northwind`.`Order Details`.`UnitPrice` * `northwind`.`Order Details`.`Quantity`) * (1 - `northwind`.`Order Details`.`Discount`)),2)) AS `ProductSales` from ((`northwind`.`Categories` join `northwind`.`Products` on((`northwind`.`Categories`.`CategoryID` = `northwind`.`Products`.`CategoryID`))) join (`northwind`.`Orders` join `northwind`.`Order Details` on((`northwind`.`Orders`.`OrderID` = `northwind`.`Order Details`.`OrderID`))) on((`northwind`.`Products`.`ProductID` = `northwind`.`Order Details`.`ProductID`))) where (`northwind`.`Orders`.`ShippedDate` between '1997-01-01' and '1997-12-31') group by `northwind`.`Categories`.`CategoryName`,`northwind`.`Products`.`ProductName`